//! 🧊️ Irregular three-dimensional slots, typed media and named constraint channels.
use super::{Wfc3dSnapshot,Tile,TileMedia3d,Color,Slot3d,SlotEdge,GraphRule};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound,FloatColumn,FloatRow,insert_ieee754}}};
use std::collections::{BTreeMap,BTreeSet};
fn index(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|_|"wfc3d ordinal overflow".into())}
fn floats(t:&str)->&'static[FloatColumn]{match t{"wfc3d_tile"=>&[FloatColumn::Binary64(5)],"wfc3d_position"=>&[FloatColumn::Binary64(3)],"wfc3d_slot"=>&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9)],_=>&[]}}
fn identity(r:FloatRow<'_>,n:usize)->Result<(),String>{if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{return Err("wfc3d entity identity or columns differ".into())}Ok(())}
fn word(r:FloatRow<'_>,i:usize)->Result<u32,String>{u32::try_from(r.integer(i)?).map_err(|_|"wfc3d unsigned32 differs".into())}
fn byte(r:FloatRow<'_>,i:usize)->Result<u8,String>{u8::try_from(r.integer(i)?).map_err(|_|"wfc3d unsigned8 color differs".into())}
fn flag(r:FloatRow<'_>,i:usize)->Result<bool,String>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err("wfc3d boolean differs".into())}}
fn rows<'a>(d:&'a SqliteDatabase,t:&str,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>,String>{let mut result=Vec::new();let mut seen=BTreeSet::new();for(i,r)in d.table(t)?.rows.iter().enumerate(){if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}let r=FloatRow::new(r,floats(t))?;if !seen.insert(r.rowid){return Err("duplicate wfc3d entity identity".into())}result.push(r);}Ok(result)}
fn ordered<'a>(mut rows:Vec<FloatRow<'a>>)->Result<Vec<FloatRow<'a>>,String>{rows.sort_by_key(|r|r.integer(2).unwrap_or(-1));for(i,r)in rows.iter().enumerate(){if r.integer(2)?!=index(i)?{return Err("wfc3d ordinals must be contiguous".into())}}Ok(rows)}
fn groups<'a>(d:&'a SqliteDatabase,t:&str,n:usize,owners:&BTreeSet<i64>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<FloatRow<'a>>>,String>{let mut map=BTreeMap::<i64,Vec<FloatRow<'a>>>::new();for(i,r)in rows(d,t,c)?.into_iter().enumerate(){identity(r,n)?;let owner=r.integer(1)?;if !owners.contains(&owner){return Err("wfc3d relationship has an unknown owner".into())}map.entry(owner).or_default().push(r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}Ok(map)}
impl ArtifactSqliteSnapshot for Wfc3dSnapshot{
const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
 let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;let mut total=1usize;for n in [self.tiles.len(),self.slots.len(),self.edges.len(),self.rules.len()]{total=total.checked_add(n).ok_or("wfc3d entity count overflow")?;p.check_rows(total)?;}for t in &self.tiles{let extra=match &t.media{TileMedia3d::Mesh{positions,indices,color}=>1usize.checked_add(positions.len()).and_then(|n|n.checked_add(indices.len())).and_then(|n|n.checked_add(usize::from(color.is_some()))).ok_or("wfc3d mesh entity count overflow")?,TileMedia3d::MeshChild{..}=>1};total=total.checked_add(extra).ok_or("wfc3d entity count overflow")?;p.check_rows(total)?;p.checkpoint()?;}
 p.insert_key("wfc3d_document",1,&[Cell::Text(&self.schema),Cell::Text(&self.seed.to_string())])?;let mut tiles=BTreeMap::new();
 for(i,t)in self.tiles.iter().enumerate(){let kind=match &t.media{TileMedia3d::Mesh{..}=>"mesh",TileMedia3d::MeshChild{..}=>"mesh_child"};let id=insert_ieee754(&mut p,"wfc3d_tile",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&t.id),t.label.as_deref().map_or(Cell::Null,Cell::Text),Cell::Real(t.weight),Cell::Text(kind)],floats("wfc3d_tile"))?;if tiles.insert(t.id.as_str(),id).is_some(){return Err("duplicate wfc3d authored tile identity".into())}match &t.media{TileMedia3d::Mesh{positions,indices,color}=>{p.insert_key("wfc3d_mesh",id,&[])?;for(i,v)in positions.iter().enumerate(){insert_ieee754(&mut p,"wfc3d_position",&[Cell::Integer(id),Cell::Integer(index(i)?),Cell::Real(*v)],floats("wfc3d_position"))?;}for(i,v)in indices.iter().enumerate(){p.insert("wfc3d_index",&[Cell::Integer(id),Cell::Integer(index(i)?),Cell::Integer(i64::from(*v))])?;}if let Some(c)=color{p.insert_key("wfc3d_color",id,&[Cell::Integer(i64::from(c.r)),Cell::Integer(i64::from(c.g)),Cell::Integer(i64::from(c.b)),Cell::Integer(i64::from(c.a))])?;}},TileMedia3d::MeshChild{child}=>{let target=&child.target;p.insert_key("wfc3d_mesh_child",id,&[Cell::Text(&child.child_id),Cell::Text(&target.artifact_id),Cell::Text(&target.dialect.artifact_kind),Cell::Text(&target.dialect.standard),Cell::Text(&target.dialect.subset)])?;}}}
 let mut slots=BTreeMap::new();for(i,s)in self.slots.iter().enumerate(){let pin=match &s.pinned_tile_id{None=>Cell::Null,Some(name)=>Cell::Integer(*tiles.get(name.as_str()).ok_or("dangling wfc3d pinned tile")?)};let id=insert_ieee754(&mut p,"wfc3d_slot",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&s.id),Cell::Real(s.x),Cell::Real(s.y),Cell::Real(s.z),Cell::Real(s.width),Cell::Real(s.height),Cell::Real(s.depth),pin],floats("wfc3d_slot"))?;if slots.insert(s.id.as_str(),id).is_some(){return Err("duplicate wfc3d authored slot identity".into())}}
 let mut edge_ids=BTreeSet::new();for(i,e)in self.edges.iter().enumerate(){if !edge_ids.insert(&e.id){return Err("duplicate wfc3d authored edge identity".into())}p.insert("wfc3d_slot_edge",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&e.id),Cell::Integer(*slots.get(e.from_slot_id.as_str()).ok_or("dangling wfc3d edge start")?),Cell::Integer(*slots.get(e.to_slot_id.as_str()).ok_or("dangling wfc3d edge end")?),Cell::Text(&e.relation)])?;}
 let mut rule_ids=BTreeSet::new();for(i,r)in self.rules.iter().enumerate(){if !rule_ids.insert(&r.id){return Err("duplicate wfc3d authored rule identity".into())}p.insert("wfc3d_rule",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&r.id),Cell::Integer(*tiles.get(r.tile_a_id.as_str()).ok_or("dangling wfc3d rule tile A")?),Cell::Integer(*tiles.get(r.tile_b_id.as_str()).ok_or("dangling wfc3d rule tile B")?),r.relation.as_deref().map_or(Cell::Null,Cell::Text),Cell::Integer(i64::from(r.allowed))])?;}
 p.finish()
}
fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
 validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let doc=FloatRow::new(d.table("wfc3d_document")?.single_row()?,&[])?;identity(doc,3)?;if doc.rowid!=1{return Err("wfc3d root identity must be one".into())}let seed=doc.text(2)?.parse::<u64>().map_err(|_|"wfc3d seed exceeds unsigned64")?;if seed.to_string()!=doc.text(2)?{return Err("wfc3d seed requires canonical decimal".into())}
 let root=BTreeSet::from([1]);let tile_rows=ordered(groups(d,"wfc3d_tile",7,&root,c)?.remove(&1).unwrap_or_default())?;let mut tile_names=BTreeMap::new();let mut tile_authored=BTreeSet::new();let mut mesh_ids=BTreeSet::new();let mut child_ids=BTreeSet::new();for(i,r)in tile_rows.iter().enumerate(){if !tile_authored.insert(r.text(3)?){return Err("duplicate wfc3d authored tile identity".into())}tile_names.insert(r.rowid,r.text(3)?);match r.text(6)?{"mesh"=>{mesh_ids.insert(r.rowid);},"mesh_child"=>{child_ids.insert(r.rowid);},_=>return Err("wfc3d media kind differs".into())}if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let mut seen=BTreeSet::new();for(i,r)in rows(d,"wfc3d_mesh",c)?.into_iter().enumerate(){identity(r,1)?;if !mesh_ids.contains(&r.rowid){return Err("wfc3d mesh has unknown or wrong-kind owner".into())}seen.insert(r.rowid);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}if seen!=mesh_ids{return Err("wfc3d mesh ownership is incomplete".into())}
 let mut positions=groups(d,"wfc3d_position",4,&mesh_ids,c)?;let mut indices=groups(d,"wfc3d_index",4,&mesh_ids,c)?;let mut colors=BTreeMap::new();for(i,r)in rows(d,"wfc3d_color",c)?.into_iter().enumerate(){identity(r,5)?;if !mesh_ids.contains(&r.rowid){return Err("wfc3d color has unknown mesh".into())}colors.insert(r.rowid,r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let mut children=BTreeMap::new();for(i,r)in rows(d,"wfc3d_mesh_child",c)?.into_iter().enumerate(){identity(r,6)?;if !child_ids.contains(&r.rowid){return Err("wfc3d child has wrong-kind or unknown owner".into())}children.insert(r.rowid,r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}if children.len()!=child_ids.len(){return Err("wfc3d child ownership is incomplete".into())}
 let slot_rows=ordered(groups(d,"wfc3d_slot",11,&root,c)?.remove(&1).unwrap_or_default())?;let mut slot_names=BTreeMap::new();let mut slot_authored=BTreeSet::new();for(i,r)in slot_rows.iter().enumerate(){if !slot_authored.insert(r.text(3)?){return Err("duplicate wfc3d authored slot identity".into())}slot_names.insert(r.rowid,r.text(3)?);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let edge_rows=ordered(groups(d,"wfc3d_slot_edge",7,&root,c)?.remove(&1).unwrap_or_default())?;let rule_rows=ordered(groups(d,"wfc3d_rule",8,&root,c)?.remove(&1).unwrap_or_default())?;
 let mut owned=Reconstruction::new(c)?;let schema=owned.text(doc.text(1)?)?;owned.scalar()?;let mut tiles=Vec::new();for r in tile_rows{owned.scalar()?;let media=if mesh_ids.contains(&r.rowid){let mut native_positions=Vec::new();for v in ordered(positions.remove(&r.rowid).unwrap_or_default())?{owned.scalar()?;native_positions.push(v.real(3)?);}let mut native_indices=Vec::new();for v in ordered(indices.remove(&r.rowid).unwrap_or_default())?{owned.scalar()?;native_indices.push(word(v,3)?);}let color=match colors.remove(&r.rowid){None=>None,Some(v)=>{for _ in 0..4{owned.scalar()?;}Some(Color{r:byte(v,1)?,g:byte(v,2)?,b:byte(v,3)?,a:byte(v,4)?})}};TileMedia3d::Mesh{positions:native_positions,indices:native_indices,color}}else{let v=children.remove(&r.rowid).ok_or("wfc3d child absent")?;let target=store::os_io::ArtifactRef{artifact_id:owned.text(v.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:owned.text(v.text(3)?)?,standard:owned.text(v.text(4)?)?,subset:owned.text(v.text(5)?)?}};TileMedia3d::MeshChild{child:store::ArtifactChild::new(owned.text(v.text(1)?)?,target)}};tiles.push(Tile{id:owned.text(r.text(3)?)?,label:r.optional_text(4)?.map(|s|owned.text(s)).transpose()?,weight:r.real(5)?,media});}
 let mut slots=Vec::new();for r in slot_rows{for _ in 0..6{owned.scalar()?;}let pin=match r.values[10]{SqliteValue::Null=>None,_=>Some(owned.text(tile_names.get(&r.integer(10)?).copied().ok_or("dangling wfc3d pinned tile")?)?)};slots.push(Slot3d{id:owned.text(r.text(3)?)?,x:r.real(4)?,y:r.real(5)?,z:r.real(6)?,width:r.real(7)?,height:r.real(8)?,depth:r.real(9)?,pinned_tile_id:pin});}
 let mut edges=Vec::new();let mut edge_ids=BTreeSet::new();for r in edge_rows{if !edge_ids.insert(r.text(3)?){return Err("duplicate wfc3d authored edge identity".into())}edges.push(SlotEdge{id:owned.text(r.text(3)?)?,from_slot_id:owned.text(slot_names.get(&r.integer(4)?).copied().ok_or("dangling wfc3d edge start")?)?,to_slot_id:owned.text(slot_names.get(&r.integer(5)?).copied().ok_or("dangling wfc3d edge end")?)?,relation:owned.text(r.text(6)?)?});owned.checkpoint()?;}
 let mut rules=Vec::new();let mut rule_ids=BTreeSet::new();for r in rule_rows{if !rule_ids.insert(r.text(3)?){return Err("duplicate wfc3d authored rule identity".into())}owned.scalar()?;rules.push(GraphRule{id:owned.text(r.text(3)?)?,tile_a_id:owned.text(tile_names.get(&r.integer(4)?).copied().ok_or("dangling wfc3d rule tile A")?)?,tile_b_id:owned.text(tile_names.get(&r.integer(5)?).copied().ok_or("dangling wfc3d rule tile B")?)?,relation:r.optional_text(6)?.map(|s|owned.text(s)).transpose()?,allowed:flag(r,7)?});}owned.checkpoint()?;Ok(Self{schema,seed,tiles,slots,edges,rules})
}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=NativeEncodingBound::new(c)?;b.add(4096)?;b.repeated(self.schema.len(),16)?;let mut total=1usize;for n in [self.slots.len(),self.edges.len(),self.tiles.len(),self.rules.len()]{total=total.checked_add(n).ok_or("wfc3d native entity overflow")?;b.check_rows(total)?;}for t in &self.tiles{b.repeated(t.id.len(),16)?;if let Some(v)=&t.label{b.repeated(v.len(),16)?;}b.add(4096)?;match &t.media{TileMedia3d::Mesh{positions,indices,color}=>{total=total.checked_add(positions.len()).and_then(|n|n.checked_add(indices.len())).ok_or("wfc3d native mesh count overflow")?;b.check_rows(total)?;b.repeated(positions.len(),2048)?;b.repeated(indices.len(),256)?;if color.is_some(){b.add(1024)?;}},TileMedia3d::MeshChild{child}=>{let target=&child.target;for v in [&child.child_id,&target.artifact_id,&target.dialect.artifact_kind,&target.dialect.standard,&target.dialect.subset]{b.repeated(v.len(),16)?;}}}}for s in &self.slots{b.repeated(s.id.len(),16)?;if let Some(v)=&s.pinned_tile_id{b.repeated(v.len(),16)?;}b.add(16384)?;}for e in &self.edges{for v in [&e.id,&e.from_slot_id,&e.to_slot_id,&e.relation]{b.repeated(v.len(),16)?;}b.add(1024)?;}for r in &self.rules{for v in [&r.id,&r.tile_a_id,&r.tile_b_id]{b.repeated(v.len(),16)?;}if let Some(v)=&r.relation{b.repeated(v.len(),16)?;}b.add(1024)?;}b.finish()}
fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;if dialect.artifact_kind!="s.wfc.wfc3d"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("wfc3d dialect differs from its owned wildcard").into())}if d.table("wfc3d_document")?.single_row()?.text(1)?!=self.schema{return Err(String::from("wfc3d projected schema differs").into())}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}
}
